CREATE TABLE `PremisesAsset` (`id` CHAR(36) NOT NULL,`name` VARCHAR(191) NOT NULL,`category` VARCHAR(60) NOT NULL,`location` VARCHAR(191) NULL,`manufacturer` VARCHAR(120) NULL,`model` VARCHAR(120) NULL,`serialNumber` VARCHAR(120) NULL,`responsibleName` VARCHAR(120) NULL,`serviceProvider` VARCHAR(191) NULL,`recurrenceDays` INTEGER NULL,`nextDueDate` DATE NULL,`active` BOOLEAN NOT NULL DEFAULT true,`notes` TEXT NULL,`createdById` CHAR(36) NOT NULL,`updatedById` CHAR(36) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `PremisesAsset_category_active_idx` (`category`,`active`),INDEX `PremisesAsset_nextDueDate_active_idx` (`nextDueDate`,`active`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PremisesInspection` (`id` CHAR(36) NOT NULL,`assetId` CHAR(36) NOT NULL,`testType` VARCHAR(191) NOT NULL,`completedDate` DATE NOT NULL,`result` VARCHAR(30) NOT NULL,`completedBy` VARCHAR(120) NOT NULL,`contractor` VARCHAR(191) NULL,`certificateReference` VARCHAR(191) NULL,`nextDueDate` DATE NULL,`notes` TEXT NULL,`createdById` CHAR(36) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `PremisesInspection_assetId_completedDate_idx` (`assetId`,`completedDate`),INDEX `PremisesInspection_result_completedDate_idx` (`result`,`completedDate`),CONSTRAINT `PremisesInspection_assetId_fkey` FOREIGN KEY (`assetId`) REFERENCES `PremisesAsset` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PremisesCorrectiveAction` (`id` CHAR(36) NOT NULL,`assetId` CHAR(36) NULL,`inspectionId` CHAR(36) NULL,`title` VARCHAR(191) NOT NULL,`priority` VARCHAR(20) NOT NULL,`status` VARCHAR(30) NOT NULL DEFAULT 'OPEN',`assignedTo` VARCHAR(120) NULL,`dueDate` DATE NULL,`completedAt` DATETIME(3) NULL,`notes` TEXT NULL,`createdById` CHAR(36) NOT NULL,`updatedById` CHAR(36) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `PremisesCorrectiveAction_status_dueDate_idx` (`status`,`dueDate`),INDEX `PremisesCorrectiveAction_assetId_idx` (`assetId`),CONSTRAINT `PremisesCorrectiveAction_assetId_fkey` FOREIGN KEY (`assetId`) REFERENCES `PremisesAsset` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,CONSTRAINT `PremisesCorrectiveAction_inspectionId_fkey` FOREIGN KEY (`inspectionId`) REFERENCES `PremisesInspection` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PremisesDocument` (`id` CHAR(36) NOT NULL,`assetId` CHAR(36) NULL,`title` VARCHAR(191) NOT NULL,`documentType` VARCHAR(60) NOT NULL,`reference` VARCHAR(191) NULL,`provider` VARCHAR(191) NULL,`issuedDate` DATE NULL,`expiryDate` DATE NULL,`documentUrl` VARCHAR(500) NULL,`notes` TEXT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdById` CHAR(36) NOT NULL,`updatedById` CHAR(36) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `PremisesDocument_documentType_active_idx` (`documentType`,`active`),INDEX `PremisesDocument_expiryDate_active_idx` (`expiryDate`,`active`),CONSTRAINT `PremisesDocument_assetId_fkey` FOREIGN KEY (`assetId`) REFERENCES `PremisesAsset` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;